# How the HR sync joined a contract's positions into one text.
SEPARATOR = ", "


def copy_positions(apps, schema_editor):
    """Each name in the joined HR text becomes a position the person holds, in HR's order."""
    Person = apps.get_model("core", "Person")
    OrganizationalPosition = apps.get_model("core", "OrganizationalPosition")
    PersonPosition = apps.get_model("core", "PersonPosition")
    for person in Person._base_manager.exclude(udb_contract_organizational_positions=""):
        names = (name.strip() for name in person.udb_contract_organizational_positions.split(SEPARATOR))
        for name in dict.fromkeys(name for name in names if name):
            position, _ = OrganizationalPosition.objects.get_or_create(name=name)
            PersonPosition.objects.create(person=person, position=position)


def join_positions(apps, schema_editor):
    """Back: the positions as one text again, in the order they were copied."""
    Person = apps.get_model("core", "Person")
    PersonPosition = apps.get_model("core", "PersonPosition")
    names_by_person = {}
    for row in PersonPosition.objects.select_related("position").order_by("pk"):
        names_by_person.setdefault(row.person_id, []).append(row.position.name)
    for person_id, names in names_by_person.items():
        joined = SEPARATOR.join(names)[:255]
        Person._base_manager.filter(pk=person_id).update(udb_contract_organizational_positions=joined)


